package list

import (
	"errors"
	"fmt"
	"strings"

	"github.com/anyproto/any-sync/commonspace/object/accountdata"
	"github.com/anyproto/any-sync/commonspace/object/acl/aclrecordproto"
	"github.com/anyproto/any-sync/commonspace/object/acl/list/listtest"
	"github.com/anyproto/any-sync/commonspace/object/acl/recordverifier"
	"github.com/anyproto/any-sync/consensus/consensusproto"
	"github.com/anyproto/any-sync/util/crypto"
)

type TestAclState struct {
	Keys *accountdata.AccountKeys
	Acl  AclList
}

type accountExpectedState struct {
	perms    AclPermissions
	status   AclStatus
	metadata []byte
	pseudoId string
	recCmd   string
}

type AclTestExecutor struct {
	owner               string
	spaceId             string
	ownerKeys           *accountdata.AccountKeys
	ownerMeta           []byte
	root                *consensusproto.RawRecordWithId
	invites             map[string]crypto.PrivKey
	actualAccounts      map[string]*TestAclState
	expectedAccounts    map[string]*accountExpectedState
	expectedPermissions map[string][]accountExpectedState
}

type ParsedArgs struct {
	Cmd     string
	Account string
	Command string
	Args    []string
}

func NewAclExecutor(spaceId string) *AclTestExecutor {
	return &AclTestExecutor{
		spaceId:             spaceId,
		invites:             map[string]crypto.PrivKey{},
		actualAccounts:      make(map[string]*TestAclState),
		expectedAccounts:    make(map[string]*accountExpectedState),
		expectedPermissions: make(map[string][]accountExpectedState),
	}
}

func NewExternalKeysAclExecutor(spaceId string, keys *accountdata.AccountKeys, ownerMeta []byte, root *consensusproto.RawRecordWithId) *AclTestExecutor {
	return &AclTestExecutor{
		spaceId:             spaceId,
		ownerKeys:           keys,
		root:                root,
		ownerMeta:           ownerMeta,
		invites:             map[string]crypto.PrivKey{},
		actualAccounts:      make(map[string]*TestAclState),
		expectedAccounts:    make(map[string]*accountExpectedState),
		expectedPermissions: make(map[string][]accountExpectedState),
	}
}

var (
	errIncorrectParts = errors.New("incorrect parts")
)

func (a *AclTestExecutor) buildBatchRequest(args []string, acl AclList, getPerm func(perm string) AclPermissions, addRec func(rec *consensusproto.RawRecordWithId) error) (afterAll []func(), err error) {
	// remove:a,b,c;add:d,rw,m1|e,r,m2;changes:f,rw|g,r;revoke:inv1id;decline:g,h;
	batchPayload := BatchRequestPayload{}
	var inviteIds []string
	for _, arg := range args {
		parts := strings.Split(arg, ":")
		if len(parts) != 2 {
			return nil, errIncorrectParts
		}
		command := parts[0]
		commandArgs := strings.Split(parts[1], "|")
		switch command {
		case "add":
			var payloads []AccountAdd
			for _, arg := range commandArgs {
				argParts := strings.Split(arg, ",")
				if len(argParts) != 3 {
					return nil, errIncorrectParts
				}
				keys, err := accountdata.NewRandom()
				if err != nil {
					return nil, err
				}
				ownerAcl := a.actualAccounts[a.owner].Acl.(*aclList)
				accountAcl, err := BuildAclListWithIdentity(keys, ownerAcl.storage, recordverifier.NewValidateFull())
				if err != nil {
					return nil, err
				}
				state := &TestAclState{
					Keys: keys,
					Acl:  accountAcl,
				}
				account := argParts[0]
				a.actualAccounts[account] = state
				a.expectedAccounts[account] = &accountExpectedState{
					perms:    getPerm(argParts[1]),
					status:   StatusActive,
					metadata: []byte(argParts[2]),
					pseudoId: account,
				}
				payloads = append(payloads, AccountAdd{
					Identity:    keys.SignKey.GetPublic(),
					Permissions: getPerm(argParts[1]),
					Metadata:    []byte(argParts[2]),
				})
			}
			defer func() {
				if err != nil {
					for _, arg := range args {
						argParts := strings.Split(arg, ",")
						account := argParts[0]
						delete(a.expectedAccounts, account)
						delete(a.actualAccounts, account)
					}
				}
			}()
			batchPayload.Additions = payloads
		case "remove":
			identities := strings.Split(commandArgs[0], ",")
			var pubKeys []crypto.PubKey
			for _, id := range identities {
				pk := a.actualAccounts[id].Keys.SignKey.GetPublic()
				pubKeys = append(pubKeys, pk)
			}
			priv, _, err := crypto.GenerateRandomEd25519KeyPair()
			if err != nil {
				return nil, err
			}
			sym := crypto.NewAES()
			payload := AccountRemovePayload{
				Identities: pubKeys,
				Change: ReadKeyChangePayload{
					MetadataKey: priv,
					ReadKey:     sym,
				},
			}
			batchPayload.Removals = payload
			afterAll = append(afterAll, func() {
				for _, id := range identities {
					a.expectedAccounts[id].status = StatusRemoved
					a.expectedAccounts[id].perms = AclPermissionsNone
				}
			})
		case "changes":
			var payloads []PermissionChangePayload
			for _, arg := range commandArgs {
				argParts := strings.Split(arg, ",")
				if len(argParts) != 2 {
					return nil, errIncorrectParts
				}
				changed := a.actualAccounts[argParts[0]].Keys.SignKey.GetPublic()
				perms := getPerm(argParts[1])
				payloads = append(payloads, PermissionChangePayload{
					Identity:    changed,
					Permissions: perms,
				})
				afterAll = append(afterAll, func() {
					a.expectedAccounts[argParts[0]].perms = perms
				})
			}
			batchPayload.Changes = payloads
		case "revoke":
			invite := a.invites[commandArgs[0]]
			invId, err := acl.AclState().GetInviteIdByPrivKey(invite)
			if err != nil {
				return nil, err
			}
			batchPayload.InviteRevokes = append(batchPayload.InviteRevokes, invId)
		case "decline":
			id := commandArgs[0]
			pk := a.actualAccounts[id].Keys.SignKey.GetPublic()
			rec, err := acl.AclState().JoinRecord(pk, false)
			if err != nil {
				return nil, err
			}
			batchPayload.Declines = append(batchPayload.Declines, rec.RecordId)
			afterAll = append(afterAll, func() {
				a.expectedAccounts[id].status = StatusDeclined
			})
		case "invite":
			inviteParts := strings.Split(commandArgs[0], ",")
			id := inviteParts[0]
			inviteIds = append(inviteIds, id)
			batchPayload.NewInvites = append(batchPayload.NewInvites, AclPermissionsNone)
		case "invite_anyone":
			inviteParts := strings.Split(commandArgs[0], ",")
			id := inviteParts[0]
			var permissions AclPermissions
			if inviteParts[1] == "r" {
				permissions = AclPermissions(aclrecordproto.AclUserPermissions_Reader)
			} else if inviteParts[1] == "rw" {
				permissions = AclPermissions(aclrecordproto.AclUserPermissions_Writer)
			} else {
				permissions = AclPermissions(aclrecordproto.AclUserPermissions_Admin)
			}
			inviteIds = append(inviteIds, id)
			batchPayload.NewInvites = append(batchPayload.NewInvites, permissions)
		case "approve":
			recs, err := acl.AclState().JoinRecords(false)
			if err != nil {
				return nil, err
			}
			argParts := strings.Split(commandArgs[0], ",")
			if len(argParts) != 2 {
				return nil, errIncorrectParts
			}
			approved := a.actualAccounts[argParts[0]].Keys.SignKey.GetPublic()
			var recId string
			for _, rec := range recs {
				if rec.RequestIdentity.Equals(approved) {
					recId = rec.RecordId
				}
			}
			if recId == "" {
				return nil, fmt.Errorf("no join records to approve")
			}
			perms := getPerm(argParts[1])
			afterAll = append(afterAll, func() {
				a.expectedAccounts[argParts[0]].status = StatusActive
				a.expectedAccounts[argParts[0]].perms = perms
			})
			batchPayload.Approvals = append(batchPayload.Approvals, RequestAcceptPayload{
				RequestRecordId: recId,
				Permissions:     perms,
			})
		}
	}
	res, err := acl.RecordBuilder().BuildBatchRequest(batchPayload)
	if err != nil {
		return nil, err
	}
	for i, id := range inviteIds {
		a.invites[id] = res.Invites[i]
	}
	return afterAll, addRec(listtest.WrapAclRecord(res.Rec))
}

func (a *AclTestExecutor) initOneToOne(parsedArgs *ParsedArgs) error {
	if len(parsedArgs.Args) != 2 {
		return errIncorrectParts
	}
	if len(a.actualAccounts) != 0 {
		return fmt.Errorf("init-onetoone must be the first command")
	}
	type accSpec struct {
		name string
	}
	specs := make([]accSpec, len(parsedArgs.Args))
	for i, raw := range parsedArgs.Args {
		parts := strings.SplitN(raw, ",", 2)
		name := strings.TrimSpace(parts[0])
		if name == "" {
			return errIncorrectParts
		}
		if len(parts) == 2 && strings.TrimSpace(parts[1]) != "" {
			return fmt.Errorf("init-onetoone does not support metadata")
		}
		specs[i].name = name
	}
	if specs[0].name == specs[1].name {
		return ErrDuplicateAccounts
	}
	accountKeys := make([]*accountdata.AccountKeys, len(specs))
	writerBytes := make([][]byte, len(specs))
	for i := range specs {
		keys, err := accountdata.NewRandom()
		if err != nil {
			return err
		}
		accountKeys[i] = keys
		writerBytes[i], err = keys.SignKey.GetPublic().Marshall()
		if err != nil {
			return err
		}
	}
	sharedKey, err := crypto.GenerateSharedKey(accountKeys[0].SignKey, accountKeys[1].SignKey.GetPublic(), crypto.AnysyncOneToOneSpacePath)
	if err != nil {
		return err
	}
	sharedPubBytes, err := sharedKey.GetPublic().Marshall()
	if err != nil {
		return err
	}
	recBuilder := NewAclRecordBuilder("", crypto.NewKeyStorage(), nil, recordverifier.NewValidateFull())
	root, err := recBuilder.BuildOneToOneRoot(RootContent{
		PrivKey:   sharedKey,
		MasterKey: sharedKey,
	}, &aclrecordproto.AclOneToOneInfo{
		Owner:   sharedPubBytes,
		Writers: writerBytes,
	})
	if err != nil {
		return err
	}
	for i, spec := range specs {
		aclList, err := newInMemoryAclWithRoot(accountKeys[i], root)
		if err != nil {
			return err
		}
		a.actualAccounts[spec.name] = &TestAclState{
			Keys: accountKeys[i],
			Acl:  aclList,
		}
		a.expectedAccounts[spec.name] = &accountExpectedState{
			perms:    AclPermissions(aclrecordproto.AclUserPermissions_Writer),
			status:   StatusActive,
			pseudoId: spec.name,
		}
	}
	a.owner = specs[0].name
	head := a.actualAccounts[a.owner].Acl.Head().Id
	var states []accountExpectedState
	for _, state := range a.expectedAccounts {
		cp := *state
		cp.recCmd = parsedArgs.Cmd
		states = append(states, cp)
	}
	a.expectedPermissions[head] = states
	return nil
}

func (a *AclTestExecutor) parseArgs(cmd string) (*ParsedArgs, error) {
	parts := strings.Split(cmd, "::")
	if len(parts) != 2 {
		return nil, errIncorrectParts
	}
	commandParts := strings.Split(parts[0], ".")
	if len(commandParts) != 2 {
		return nil, errIncorrectParts
	}
	account := commandParts[0]
	command := commandParts[1]
	args := strings.Split(parts[1], ";")
	if len(args) == 0 {
		return nil, errIncorrectParts
	}
	return &ParsedArgs{
		Cmd:     cmd,
		Account: account,
		Command: command,
		Args:    args,
	}, nil
}

func (a *AclTestExecutor) Execute(cmdStr string) (err error) {
	parsedArgs, err := a.parseArgs(cmdStr)
	if err != nil {
		return
	}

	if parsedArgs.Command == "init-onetoone" {
		return a.initOneToOne(parsedArgs)
	}

	var isNewAccount bool
	if _, exists := a.actualAccounts[parsedArgs.Account]; !exists {
		if len(a.actualAccounts) > 0 {
			rootAccount := a.actualAccounts[a.owner]
			if rootAccount != nil && rootAccount.Acl.AclState().IsOneToOne() {
				return ErrAddRecordOneToOne
			}
		}
		isNewAccount = true
		keys, err := accountdata.NewRandom()
		if err != nil {
			return err
		}
		if len(a.expectedAccounts) == 0 {
			meta := []byte(parsedArgs.Account)
			var acl AclList
			if a.ownerKeys == nil {
				acl, err = newInMemoryDerivedAclMetadata(a.spaceId, keys, meta)
				if err != nil {
					return err
				}
			} else {
				keys = a.ownerKeys
				meta = a.ownerMeta
				acl, err = newInMemoryAclWithRoot(keys, a.root)
				if err != nil {
					return err
				}
			}
			state := &TestAclState{
				Keys: keys,
				Acl:  acl,
			}
			a.actualAccounts[parsedArgs.Account] = state
			a.expectedAccounts[parsedArgs.Account] = &accountExpectedState{
				perms:    AclPermissions(aclrecordproto.AclUserPermissions_Owner),
				status:   StatusActive,
				metadata: meta,
				pseudoId: parsedArgs.Account,
			}
			a.owner = parsedArgs.Account
			return nil
		} else {
			ownerAcl := a.actualAccounts[a.owner].Acl.(*aclList)
			copyStorage := ownerAcl.storage.(*inMemoryStorage).Copy()
			accountAcl, err := BuildAclListWithIdentity(keys, copyStorage, recordverifier.NewValidateFull())
			if err != nil {
				return err
			}
			state := &TestAclState{
				Keys: keys,
				Acl:  accountAcl,
			}
			a.actualAccounts[parsedArgs.Account] = state
			a.expectedAccounts[parsedArgs.Account] = &accountExpectedState{
				metadata: []byte(parsedArgs.Account),
				pseudoId: parsedArgs.Account,
			}
		}
	} else if a.expectedAccounts[parsedArgs.Account].status == StatusRemoved {
		keys := a.actualAccounts[parsedArgs.Account].Keys
		ownerAcl := a.actualAccounts[a.owner].Acl.(*aclList)
		copyStorage := ownerAcl.storage.(*inMemoryStorage).Copy()
		accountAcl, err := BuildAclListWithIdentity(keys, copyStorage, recordverifier.NewValidateFull())
		if err != nil {
			return err
		}
		a.actualAccounts[parsedArgs.Account].Acl = accountAcl
	}
	acl := a.actualAccounts[parsedArgs.Account].Acl
	if acl.AclState().IsOneToOne() {
		return ErrAddRecordOneToOne
	}
	var afterAll []func()
	defer func() {
		if err != nil {
			if !isNewAccount {
				return
			}
			delete(a.expectedAccounts, parsedArgs.Account)
			delete(a.actualAccounts, parsedArgs.Account)
		} else {
			for _, f := range afterAll {
				f()
			}
			head := acl.Head().Id
			var states []accountExpectedState
			for _, state := range a.expectedAccounts {
				cp := *state
				cp.recCmd = parsedArgs.Cmd
				states = append(states, cp)
			}
			a.expectedPermissions[head] = states
		}
	}()
	addRec := func(rec *consensusproto.RawRecordWithId) error {
		for _, acc := range a.actualAccounts {
			err := acc.Acl.AddRawRecord(rec)
			if err != nil {
				return err
			}
		}
		return nil
	}
	getPerm := func(perm string) AclPermissions {
		var aclPerm aclrecordproto.AclUserPermissions
		switch perm {
		case "own":
			aclPerm = aclrecordproto.AclUserPermissions_Owner
		case "adm":
			aclPerm = aclrecordproto.AclUserPermissions_Admin
		case "rw":
			aclPerm = aclrecordproto.AclUserPermissions_Writer
		case "none":
			aclPerm = aclrecordproto.AclUserPermissions_None
		case "r":
			aclPerm = aclrecordproto.AclUserPermissions_Reader
		case "g":
			aclPerm = aclrecordproto.AclUserPermissions_Guest
		}
		return AclPermissions(aclPerm)
	}
	switch parsedArgs.Command {
	case "join":
		invite := a.invites[parsedArgs.Args[0]]
		requestJoin, err := acl.RecordBuilder().BuildRequestJoin(RequestJoinPayload{
			InviteKey: invite,
			Metadata:  []byte(parsedArgs.Account),
		})
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(requestJoin))
		if err != nil {
			return err
		}
		a.expectedAccounts[parsedArgs.Account].status = StatusJoining
	case "invite":
		res, err := acl.RecordBuilder().BuildInvite()
		if err != nil {
			return err
		}
		a.invites[parsedArgs.Args[0]] = res.InviteKey
		err = addRec(listtest.WrapAclRecord(res.InviteRec))
		if err != nil {
			return err
		}
	case "invite_change":
		var permissions AclPermissions
		inviteParts := strings.Split(parsedArgs.Args[0], ",")
		if inviteParts[1] == "r" {
			permissions = AclPermissions(aclrecordproto.AclUserPermissions_Reader)
		} else if inviteParts[1] == "rw" {
			permissions = AclPermissions(aclrecordproto.AclUserPermissions_Writer)
		} else {
			permissions = AclPermissions(aclrecordproto.AclUserPermissions_Admin)
		}
		invite := a.invites[inviteParts[0]]
		invId, err := acl.AclState().GetInviteIdByPrivKey(invite)
		if err != nil {
			return err
		}
		res, err := acl.RecordBuilder().BuildInviteChange(InviteChangePayload{
			IniviteRecordId: invId,
			Permissions:     permissions,
		})
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
	case "invite_anyone":
		var permissions AclPermissions
		inviteParts := strings.Split(parsedArgs.Args[0], ",")
		if inviteParts[1] == "r" {
			permissions = AclPermissions(aclrecordproto.AclUserPermissions_Reader)
		} else if inviteParts[1] == "rw" {
			permissions = AclPermissions(aclrecordproto.AclUserPermissions_Writer)
		} else {
			permissions = AclPermissions(aclrecordproto.AclUserPermissions_Admin)
		}
		res, err := acl.RecordBuilder().BuildInviteAnyone(permissions)
		if err != nil {
			return err
		}
		a.invites[inviteParts[0]] = res.InviteKey
		err = addRec(listtest.WrapAclRecord(res.InviteRec))
		if err != nil {
			return err
		}
	case "batch":
		afterAll, err = a.buildBatchRequest(parsedArgs.Args, acl, getPerm, addRec)
		if err != nil {
			return err
		}
	case "approve":
		recs, err := acl.AclState().JoinRecords(false)
		if err != nil {
			return err
		}
		argParts := strings.Split(parsedArgs.Args[0], ",")
		if len(argParts) != 2 {
			return errIncorrectParts
		}
		approved := a.actualAccounts[argParts[0]].Keys.SignKey.GetPublic()
		var recId string
		for _, rec := range recs {
			if rec.RequestIdentity.Equals(approved) {
				recId = rec.RecordId
			}
		}
		if recId == "" {
			return fmt.Errorf("no join records to approve")
		}
		perms := getPerm(argParts[1])
		res, err := acl.RecordBuilder().BuildRequestAccept(RequestAcceptPayload{
			RequestRecordId: recId,
			Permissions:     perms,
		})
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
		a.expectedAccounts[argParts[0]].status = StatusActive
		a.expectedAccounts[argParts[0]].perms = perms
	case "ownership_change":
		argParts := strings.Split(parsedArgs.Args[0], ",")
		newOwner := a.actualAccounts[argParts[0]].Keys.SignKey.GetPublic()
		perms := getPerm(argParts[1])
		ownershipChange := OwnershipChangePayload{
			NewOwner:            newOwner,
			OldOwnerPermissions: perms,
		}
		afterAll = append(afterAll, func() {
			a.expectedAccounts[argParts[0]].perms = AclPermissionsOwner
			a.expectedAccounts[parsedArgs.Account].perms = perms
		})
		res, err := acl.RecordBuilder().BuildOwnershipChange(ownershipChange)
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
	case "changes":
		var payloads []PermissionChangePayload
		for _, arg := range parsedArgs.Args {
			argParts := strings.Split(arg, ",")
			if len(argParts) != 2 {
				return errIncorrectParts
			}
			changed := a.actualAccounts[argParts[0]].Keys.SignKey.GetPublic()
			perms := getPerm(argParts[1])
			payloads = append(payloads, PermissionChangePayload{
				Identity:    changed,
				Permissions: perms,
			})
			afterAll = append(afterAll, func() {
				a.expectedAccounts[argParts[0]].perms = perms
			})
		}
		permissionChanges := PermissionChangesPayload{Changes: payloads}
		res, err := acl.RecordBuilder().BuildPermissionChanges(permissionChanges)
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
	case "add":
		var payloads []AccountAdd
		for _, arg := range parsedArgs.Args {
			argParts := strings.Split(arg, ",")
			if len(argParts) != 3 {
				return errIncorrectParts
			}
			keys, err := accountdata.NewRandom()
			if err != nil {
				return err
			}
			ownerAcl := a.actualAccounts[a.owner].Acl.(*aclList)
			accountAcl, err := BuildAclListWithIdentity(keys, ownerAcl.storage, recordverifier.NewValidateFull())
			if err != nil {
				return err
			}
			state := &TestAclState{
				Keys: keys,
				Acl:  accountAcl,
			}
			parsedArgs.Account = argParts[0]
			a.actualAccounts[parsedArgs.Account] = state
			a.expectedAccounts[parsedArgs.Account] = &accountExpectedState{
				perms:    getPerm(argParts[1]),
				status:   StatusActive,
				metadata: []byte(argParts[2]),
				pseudoId: parsedArgs.Account,
			}
			payloads = append(payloads, AccountAdd{
				Identity:    keys.SignKey.GetPublic(),
				Permissions: getPerm(argParts[1]),
				Metadata:    []byte(argParts[2]),
			})
		}
		defer func() {
			if err != nil {
				for _, arg := range parsedArgs.Args {
					argParts := strings.Split(arg, ",")
					account := argParts[0]
					delete(a.expectedAccounts, account)
					delete(a.actualAccounts, account)
				}
			}
		}()
		res, err := acl.RecordBuilder().BuildAccountsAdd(AccountsAddPayload{Additions: payloads})
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
	case "invite_join":
		var permissions AclPermissions
		inviteParts := strings.Split(parsedArgs.Args[0], ",")
		if len(inviteParts) > 1 {
			if inviteParts[1] == "r" {
				permissions = AclPermissions(aclrecordproto.AclUserPermissions_Reader)
			} else if inviteParts[1] == "rw" {
				permissions = AclPermissions(aclrecordproto.AclUserPermissions_Writer)
			} else {
				permissions = AclPermissions(aclrecordproto.AclUserPermissions_Admin)
			}
		}
		invite := a.invites[inviteParts[0]]
		inviteJoin, err := acl.RecordBuilder().BuildInviteJoinWithoutApprove(InviteJoinPayload{
			InviteKey:   invite,
			Metadata:    []byte(parsedArgs.Account),
			Permissions: permissions,
		})
		if err != nil {
			return err
		}
		invId, err := acl.AclState().GetInviteIdByPrivKey(invite)
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(inviteJoin))
		if err != nil {
			return err
		}
		a.expectedAccounts[parsedArgs.Account].status = StatusActive
		if permissions == AclPermissionsNone {
			a.expectedAccounts[parsedArgs.Account].perms = acl.AclState().invites[invId].Permissions
		} else {
			a.expectedAccounts[parsedArgs.Account].perms = permissions
		}
	case "remove":
		identities := strings.Split(parsedArgs.Args[0], ",")
		var pubKeys []crypto.PubKey
		for _, id := range identities {
			pk := a.actualAccounts[id].Keys.SignKey.GetPublic()
			pubKeys = append(pubKeys, pk)
		}
		priv, _, err := crypto.GenerateRandomEd25519KeyPair()
		if err != nil {
			return err
		}
		sym := crypto.NewAES()
		res, err := acl.RecordBuilder().BuildAccountRemove(AccountRemovePayload{
			Identities: pubKeys,
			Change: ReadKeyChangePayload{
				MetadataKey: priv,
				ReadKey:     sym,
			},
		})
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
		for _, id := range identities {
			a.expectedAccounts[id].status = StatusRemoved
			a.expectedAccounts[id].perms = AclPermissionsNone
		}
	case "request_remove":
		id := parsedArgs.Args[0]
		res, err := acl.RecordBuilder().BuildRequestRemove()
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
		a.expectedAccounts[id].status = StatusRemoving
	case "decline":
		id := parsedArgs.Args[0]
		pk := a.actualAccounts[id].Keys.SignKey.GetPublic()
		rec, err := acl.AclState().JoinRecord(pk, false)
		if err != nil {
			return err
		}
		res, err := acl.RecordBuilder().BuildRequestDecline(rec.RecordId)
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
		a.expectedAccounts[id].status = StatusDeclined
	case "cancel":
		id := parsedArgs.Args[0]
		pk := a.actualAccounts[id].Keys.SignKey.GetPublic()
		rec, err := acl.AclState().Record(pk)
		if err != nil {
			return err
		}
		res, err := acl.RecordBuilder().BuildRequestCancel(rec.RecordId)
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
		if rec.Type == RequestTypeJoin {
			a.expectedAccounts[id].status = StatusCanceled
		} else {
			a.expectedAccounts[id].status = StatusActive
		}
	case "space_options":
		deleteRestricted := parsedArgs.Args[0] == "restrict_delete"
		res, err := acl.RecordBuilder().BuildSpaceOptionsChange(&aclrecordproto.AclSpaceOptions{
			DeleteRestricted: deleteRestricted,
		})
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(res))
		if err != nil {
			return err
		}
	case "revoke":
		invite := a.invites[parsedArgs.Args[0]]
		invId, err := acl.AclState().GetInviteIdByPrivKey(invite)
		if err != nil {
			return err
		}
		requestJoin, err := acl.RecordBuilder().BuildInviteRevoke(invId)
		if err != nil {
			return err
		}
		err = addRec(listtest.WrapAclRecord(requestJoin))
		if err != nil {
			return err
		}
	default:
		return fmt.Errorf("unexpected")
	}
	return nil
}

func (a *AclTestExecutor) ActualAccounts() map[string]*TestAclState {
	return a.actualAccounts
}

